# oee/infrastructure/caches.py # Cache never raises. from app.core.logging import logger   class RedisoeeCache:     """Redis cache for oee (never-raise)."""      def __init__(self, redis_client):         self.redis = redis_client      async def get(self, key: str):         try:             return await self.redis.get(f"oee:{key}")         except Exception as e:             logger.warning("oee.cache.get.failed", error=str(e))             return None      async def set(self, key: str, value: str, ttl: int = 300) -> None:         try:             await self.redis.setex(f"oee:{key}", ttl, value)         except Exception as e:             logger.warning("oee.cache.set.failed", error=str(e))      async def delete(self, key: str) -> None:         try:             await self.redis.delete(f"oee:{key}")         except Exception as e:             logger.warning("oee.cache.del.failed", error=str(e))